const seed={services:[['Hospitalidade corporativa','Recepção, acolhimento e acompanhamento de convidados e equipes durante toda a experiência.'],['Suporte a expositores','Apoio operacional para empresas expositoras, do planejamento à execução no pavilhão.'],['Coordenação de equipes','Seleção, preparação e supervisão de profissionais alinhados ao padrão de cada projeto.'],['Atendimento em estandes','Equipes preparadas para recepcionar, orientar e apoiar a rotina comercial do estande.'],['Credenciamento e orientação','Organização de fluxos, controle de acesso e direcionamento claro de participantes.'],['Apoio operacional','Soluções sob medida para demandas de bastidores, montagem e funcionamento do evento.']],messages:[{name:'Contato demonstrativo',company:'Empresa exemplo',event:'Feira — exemplo',status:'Nova'}]};
let data=JSON.parse(localStorage.getItem('giordano_demo')||'null')||seed;let route=(location.hash||'#home').slice(1);const app=document.querySelector('#app');
const header=()=>`<div class="topbar"><div class="container"><span>Atendimento em todo o Brasil</span><span>Hospitalidade • Operação • Confiança</span></div></div><nav class="nav"><div class="container" style="display:flex;align-items:center;justify-content:space-between"><a class="brand" href="#home"><span class="mark">G</span><span>Giordano Eventos</span></a><button class="menu" aria-label="Abrir menu" onclick="document.querySelector('.navlinks').classList.toggle('open')">☰</button><div class="navlinks"><a href="#about">Quem somos</a><a href="#services">Serviços</a><a href="#portfolio">Portfólio</a><a href="#clients">Clientes</a><a href="#team">Nossa equipe</a><a class="btn primary" href="#contact">Solicitar proposta</a></div></div></nav>`;
const footer=()=>`<footer><div class="container"><div class="footer-grid"><div><div class="brand"><span class="mark">G</span><span>Giordano Eventos</span></div><p>Hospitalidade e suporte operacional para feiras e eventos corporativos em todo o Brasil.</p></div><div><strong>Navegação</strong><a href="#about">Quem somos</a><a href="#services">Serviços</a><a href="#portfolio">Portfólio</a></div><div><strong>Contato</strong><p>[E-MAIL A DEFINIR]</p><p>[WHATSAPP A DEFINIR]</p><p>[REDES SOCIAIS A DEFINIR]</p></div></div><div class="copyright">© ${new Date().getFullYear()} Giordano Eventos. Protótipo visual — informações de contato e cases aguardam conteúdo oficial.</div></div></footer>`;
const services=()=>`<div class="service-grid">${data.services.map((s,i)=>`<article class="service"><span class="service-num">0${i+1}</span><h3>${s[0]}</h3><p>${s[1]}</p></article>`).join('')}</div>`;
const profiles=()=>`<div class="team-list"><article class="profile"><div><span class="eyebrow">01 — Fundadora</span><h3>Maria Ruth Giordano</h3><div class="role">Proprietária e fundadora</div><p>[APRESENTAÇÃO PROFISSIONAL A SER FORNECIDA] Espaço reservado para apresentar a trajetória de Maria Ruth, sua experiência no setor de eventos e a visão que orienta o trabalho da Giordano Eventos.</p><div class="profile-grid"><div><h4>Formação</h4><p>[INFORMAÇÃO A COMPLETAR]</p></div><div><h4>Experiência</h4><p>Aproximadamente 20 anos no mercado de eventos.</p></div><div><h4>Especialidades</h4><p>[INFORMAÇÕES A COMPLETAR]</p></div><div><h4>Links profissionais</h4><p>[LINKS A COMPLETAR]</p></div></div></div><div class="portrait">FOTO PROFISSIONAL<br>MARIA RUTH<br>proporção 5:7</div></article><article class="profile"><div><span class="eyebrow">02 — Sócia</span><h3>Roberta Mansur Sperandio</h3><div class="role">Sócia</div><p>[APRESENTAÇÃO PROFISSIONAL A SER FORNECIDA] Espaço reservado para apresentar a atuação de Roberta, sua formação, experiência e contribuição para os projetos da Giordano Eventos.</p><div class="profile-grid"><div><h4>Formação</h4><p>[INFORMAÇÃO A COMPLETAR]</p></div><div><h4>Experiência</h4><p>[INFORMAÇÃO A COMPLETAR]</p></div><div><h4>Especialidades</h4><p>[INFORMAÇÕES A COMPLETAR]</p></div><div><h4>Links profissionais</h4><p>[LINKS A COMPLETAR]</p></div></div></div><div class="portrait">FOTO PROFISSIONAL<br>ROBERTA<br>proporção 5:7</div></article></div>`;
const proposal=()=>`<section class="cta"><div class="container cta-grid"><div><span class="eyebrow" style="color:var(--gold)">Vamos conversar</span><h2>Seu próximo evento começa com uma operação bem planejada.</h2><p>Conte-nos o que sua empresa precisa. Retornaremos com uma proposta alinhada ao formato, local e período do evento.</p></div><form class="form" onsubmit="sendProposal(event)"><div class="field"><label>Nome</label><input name="name" required placeholder="Seu nome"></div><div class="field"><label>Empresa</label><input name="company" required placeholder="Nome da empresa"></div><div class="field"><label>WhatsApp</label><input required placeholder="(00) 00000-0000"></div><div class="field"><label>E-mail</label><input type="email" required placeholder="voce@empresa.com.br"></div><div class="field"><label>Evento</label><input name="event" placeholder="Nome do evento"></div><div class="field"><label>Cidade/Estado</label><input placeholder="Cidade / UF"></div><div class="field full"><label>Data ou período</label><input placeholder="Quando será realizado?"></div><div class="field full"><label>Mensagem</label><textarea placeholder="Conte um pouco sobre a necessidade"></textarea></div><div class="field full"><button class="btn light" type="submit">Enviar solicitação →</button></div></form></div></section>`;
function publicPage(content){return `<div class="shell">${header()}${content}${footer()}</div>`}
const pages={
home:()=>publicPage(`<main><section class="hero"><div class="hero-grid"><div class="hero-copy"><span class="eyebrow">Experiência que acolhe. Operação que funciona.</span><h1>Excelência em <em>hospitalidade</em> para feiras e eventos corporativos.</h1><p>Há aproximadamente duas décadas, apoiamos empresas expositoras com equipes preparadas, atendimento cuidadoso e execução organizada em todo o Brasil.</p><div class="actions"><a href="#contact" class="btn primary">Solicitar proposta →</a><a href="#portfolio" class="btn">Conheça nosso portfólio</a></div></div><div class="hero-panel"><div class="hero-stat"><strong>20</strong><span>anos de experiência aproximada no mercado</span></div><div class="hero-stat"><strong>BR</strong><span>atuação em feiras e eventos por todo o país</span></div></div></section><section><div class="container intro-grid"><div><span class="eyebrow">Quem somos</span><div class="rule"></div></div><div><p class="intro-copy">Presença profissional, atenção aos detalhes e tranquilidade para quem expõe.</p><p>A Giordano Eventos atua nos bastidores e na linha de frente de feiras e encontros corporativos. Cada projeto recebe uma equipe alinhada, orientação clara e acompanhamento próximo.</p><a class="btn" href="#about">Conheça nossa história →</a></div></div></section><section class="cream"><div class="container"><div class="section-head"><div><span class="eyebrow">O que fazemos</span><h2>Serviços que valorizam a sua marca.</h2></div><p>Do primeiro contato ao encerramento, apoiamos os pontos essenciais para que expositores e convidados tenham uma experiência consistente.</p></div>${services()}</div></section><section><div class="container"><div class="section-head"><div><span class="eyebrow">Portfólio</span><h2>Feiras e eventos</h2></div><a href="#portfolio" class="btn">Ver portfólio completo</a></div><div class="portfolio-grid"><article class="event-card"><div class="placeholder">Imagem ilustrativa — substituir por foto real</div><div></div><div class="event-content"><span class="event-meta">[EVENTO DEMONSTRATIVO] • Cidade/UF</span><h3>Nome do evento a inserir</h3><span class="placeholder-note">Conteúdo aguardando material real</span></div></article><div><article class="event-card small"><div class="placeholder">Imagem ilustrativa</div></article><article class="event-card small" style="margin-top:20px;background:var(--gold)"><div class="placeholder">Imagem ilustrativa</div></article></div></div></div></section><section class="cream"><div class="container"><div class="section-head"><div><span class="eyebrow">Quem confia</span><h2>Nossos clientes</h2></div><p>Este espaço receberá somente marcas e empresas autorizadas pela Giordano Eventos.</p></div><div class="logos">${Array.from({length:5},(_,i)=>`<div class="logo-box">Logotipo do cliente ${i+1}<br>[placeholder]</div>`).join('')}</div></div></section><section><div class="container"><div class="section-head"><div><span class="eyebrow">Nossa equipe</span><h2>Experiência à frente de cada projeto.</h2></div></div>${profiles()}</div></section>${proposal()}</main>`),
about:()=>publicPage(`<main><div class="page-head"><div class="container"><span class="eyebrow">Quem somos</span><h1>Experiência que se traduz em confiança.</h1><p>Uma trajetória construída no atendimento a empresas expositoras, com cuidado humano e organização em cada etapa.</p></div></div><section><div class="container intro-grid"><div><span class="eyebrow">Nossa história</span></div><div><p class="intro-copy">Há aproximadamente 20 anos, transformando demandas complexas em experiências bem conduzidas.</p><p>[TEXTO INSTITUCIONAL A SER VALIDADO] A Giordano Eventos nasceu da experiência prática em feiras e eventos corporativos. Atua com hospitalidade, suporte operacional e coordenação de equipes, atendendo projetos em diferentes cidades brasileiras.</p><p>Seu trabalho combina proximidade no relacionamento, preparação cuidadosa e presença ativa durante a execução.</p></div></div></section>${proposal()}</main>`),
services:()=>publicPage(`<main><div class="page-head"><div class="container"><span class="eyebrow">Serviços</span><h1>Suporte completo, na medida de cada evento.</h1><p>Estruturamos equipes e rotinas conforme a necessidade de cada expositor, local e público.</p></div></div><section><div class="container">${services()}</div></section>${proposal()}</main>`),
portfolio:()=>publicPage(`<main><div class="page-head"><div class="container"><span class="eyebrow">Portfólio</span><h1>Experiências realizadas com presença e precisão.</h1><p>Os projetos abaixo são marcadores de posição. Nenhum nome de evento, empresa ou case fictício está sendo apresentado como trabalho real.</p></div></div><section><div class="container event-detail"><aside class="facts"><div class="fact"><small>Evento</small>[NOME REAL A INSERIR]</div><div class="fact"><small>Local</small>[CIDADE / ESTADO]</div><div class="fact"><small>Período</small>[DATA OU PERÍODO]</div><div class="fact"><small>Cliente</small>[CLIENTE AUTORIZADO]</div><div class="fact"><small>Serviços realizados</small>[SERVIÇOS A DESCREVER]</div><p>[DESCRIÇÃO DO CASE A SER FORNECIDA]</p></aside><div class="gallery"><div class="gallery-placeholder">FOTO PRINCIPAL DO EVENTO<br>[legenda própria]</div>${Array.from({length:4},(_,i)=>`<div class="gallery-placeholder">FOTO ${i+2}<br>[legenda própria]</div>`).join('')}</div></div></section>${proposal()}</main>`),
clients:()=>publicPage(`<main><div class="page-head"><div class="container"><span class="eyebrow">Clientes</span><h1>Relações construídas com profissionalismo.</h1><p>Logotipos e nomes serão publicados somente após o envio e a autorização do material oficial.</p></div></div><section><div class="container"><div class="logos">${Array.from({length:10},(_,i)=>`<div class="logo-box">Cliente ${i+1}<br>[aguardando logotipo]</div>`).join('')}</div></div></section>${proposal()}</main>`),
team:()=>publicPage(`<main><div class="page-head"><div class="container"><span class="eyebrow">Nossa equipe</span><h1>Liderança próxima, execução consistente.</h1><p>Perfis individuais para apresentar formação, trajetória e especialidades das profissionais à frente da empresa.</p></div></div><section><div class="container">${profiles()}</div></section>${proposal()}</main>`),
contact:()=>publicPage(`<main><div class="page-head"><div class="container"><span class="eyebrow">Contato</span><h1>Conte-nos sobre seu próximo evento.</h1><p>Preencha as informações principais. Na versão definitiva, a solicitação será registrada com segurança no painel administrativo.</p></div></div>${proposal()}</main>`),
admin:adminPage};
function adminPage(){const section=window.adminSection||'Dashboard';let body='';if(section==='Dashboard')body=`<div class="stats"><div class="stat"><span>Novas mensagens</span><strong>${data.messages.filter(m=>m.status==='Nova').length}</strong></div><div class="stat"><span>Serviços ativos</span><strong>${data.services.length}</strong></div><div class="stat"><span>Eventos publicados</span><strong>0</strong></div><div class="stat"><span>Clientes cadastrados</span><strong>0</strong></div></div><div class="admin-card"><h2>Solicitações recentes</h2><table class="admin-table"><tr><th>Nome</th><th>Empresa</th><th>Evento</th><th>Status</th></tr>${data.messages.map(m=>`<tr><td>${m.name}</td><td>${m.company}</td><td>${m.event}</td><td><span class="badge">${m.status}</span></td></tr>`).join('')}</table></div>`;else if(section==='Serviços')body=`<div class="admin-card"><h2>Serviços</h2><p>Edite os textos demonstrativos abaixo. As alterações ficam salvas somente neste navegador.</p><div class="edit-form">${data.services.map((s,i)=>`<div class="field"><label>Serviço ${i+1}</label><input value="${s[0]}" onchange="editService(${i},0,this.value)"><textarea onchange="editService(${i},1,this.value)">${s[1]}</textarea></div>`).join('')}</div></div>`;else if(section==='Mensagens / Orçamentos')body=`<div class="admin-card"><h2>Mensagens e orçamentos</h2><table class="admin-table"><tr><th>Nome</th><th>Empresa</th><th>Evento</th><th>Status</th></tr>${data.messages.map((m,i)=>`<tr><td>${m.name}</td><td>${m.company}</td><td>${m.event}</td><td><select onchange="setStatus(${i},this.value)">${['Nova','Em atendimento','Respondida','Arquivada'].map(x=>`<option ${m.status===x?'selected':''}>${x}</option>`).join('')}</select></td></tr>`).join('')}</table></div>`;else body=`<div class="admin-card"><h2>${section}</h2><div class="notice">Protótipo visual: esta área demonstra a organização do futuro CMS. O cadastro definitivo, uploads e acesso por senha serão ativados na segunda etapa com D1, R2 e autenticação.</div><div class="edit-form"><div class="field full"><label>Título / Nome</label><input placeholder="Conteúdo editável"></div><div class="field full"><label>Texto / Descrição</label><textarea placeholder="Conteúdo editável"></textarea></div><div class="field"><label>Imagem ou arquivo</label><input type="file" disabled></div><div class="field"><label>Ordem</label><input type="number" value="1"></div><div class="field full"><button class="btn primary" onclick="toast('Alterações demonstrativas salvas')">Salvar alterações</button></div></div></div>`;const nav=['Dashboard','Quem Somos','Serviços','Portfólio / Eventos','Clientes','Perfis Profissionais','Mensagens / Orçamentos','Contato e Redes','Usuários'];return `<div class="admin"><aside class="admin-side"><div class="admin-brand"><div class="brand"><span class="mark">G</span><span>Admin</span></div></div><div class="admin-nav">${nav.map(n=>`<button class="${section===n?'active':''}" onclick="showAdmin('${n.replaceAll("'","\\'")}')">${n}</button>`).join('')}</div><a href="#home" class="btn light" style="margin-top:28px;width:100%">← Ver site</a></aside><main class="admin-main"><div class="notice">Modo demonstração — sem banco de dados, login real ou uploads nesta etapa.</div><div class="admin-top"><h1>${section}</h1><button class="btn primary" onclick="toast('Ação disponível na versão definitiva')">+ Adicionar</button></div>${body}</main></div>`}
function showAdmin(s){window.adminSection=s;render()}function editService(i,k,v){data.services[i][k]=v;save();toast('Serviço atualizado neste navegador')}function setStatus(i,v){data.messages[i].status=v;save();toast('Status atualizado')}function save(){localStorage.setItem('giordano_demo',JSON.stringify(data))}function toast(msg){document.querySelector('.toast')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="toast">${msg}</div>`);setTimeout(()=>document.querySelector('.toast')?.remove(),2400)}function sendProposal(e){e.preventDefault();const f=new FormData(e.target);data.messages.unshift({name:f.get('name'),company:f.get('company'),event:f.get('event')||'Não informado',status:'Nova'});save();e.target.reset();toast('Solicitação registrada no protótipo')}function render(){route=(location.hash||'#home').slice(1);app.innerHTML=(pages[route]||pages.home)();scrollTo(0,0)}window.addEventListener('hashchange',render);render();
if(document.modelContext?.registerTool){document.modelContext.registerTool({name:'submit_proposal_demo',title:'Registrar solicitação demonstrativa',description:'Registra uma solicitação de proposta somente no protótipo local da Giordano Eventos.',inputSchema:{type:'object',properties:{name:{type:'string'},company:{type:'string'},event:{type:'string'}},required:['name','company'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input?.name||!input?.company)throw new Error('Nome e empresa são obrigatórios');const item={name:input.name,company:input.company,event:input.event||'Não informado',status:'Nova'};data.messages.unshift(item);save();if(route==='admin')render();return {status:'saved_in_demo',message:item}}}).catch?.(()=>{})}
